function StoreItem:CalcRefreshTime()
    if self.activityUuid then
        if self.ShownData.activityTimeLeft ~= -1 then
            self._trulyRefresh = math.min(RefreshSecond, self.ShownData.activityTimeLeft)
        else
            self._trulyRefresh = RefreshSecond
        end
    else
        if self.ShownData.nextRefreshLeftSeconds ~= -1 then
            self._trulyRefresh = math.min(RefreshSecond, self.ShownData.nextRefreshLeftSeconds)
        else
            self._trulyRefresh = RefreshSecond
        end
    end
end

