function StoreItem:InitHandler()
    -- 初始化底部页签点击
    for i, v in ipairs(VarietyStoreGroup) do
        local btn = self.CommonTopLabelGroup:Find("Button" .. i)
        if not isNull(btn) then
            SetButtonAction(btn, function()
                if self.OpenId ~= v then
                    self.OpenId = v
                    self:EnterStore()
                end
            end)
        end
    end

    SetButtonAction(self.BtnExchange, function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.StoreExchange, parameters = { OpenId = self.OpenId } })
    end)
end

function StoreItem:InitView()
    if self.activityUuid then
        KTool.SetActive(self.CommonTopLabelGroup, false)
    else
        KTool.SetActive(self.CommonTopLabelGroup, true)
        self:InitStoreName()
        
        for i, v in ipairs(VarietyStoreGroup) do
            self:RefreshTabState(v, false)
        end
    end

    GameUtils.BindRedPoint(Constants.RedPointConst.GroceryExchangeFrag, self.BtnExchange, true, Vector2(-10, -6))
end

function StoreItem:InitData()
    if self.activityUuid then
        -- 处理活动商店
        GameUtils.Request(Interfaces.StoreActivityHome, {activityUuid = self.activityUuid, activityType = self.activityType}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_enter_one)
                self.ActivityStoreData = self:ConvertActivityStoreData(response.data)
                self:GetStoreData()
                self:CalcRefreshTime()
                self:StartActivityTimer()
                self:EnterStore()
            end
        end)
    else
        GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                local comp = StoreUtils.GetStoreComp()
                comp:InitialStore(response.data)
                StoreShared:StartTimer(comp)

                CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_enter_one)

                self:GetStoreData(comp)
                self:CalcRefreshTime()
                self:AddListener()
                self:EnterStore()
            end
        end)
    end
end

---转换活动商店数据
function StoreItem:ConvertActivityStoreData(requestData)
    local listData = {}
    local products = requestData.products
    for i = 1, #products do
        products[i].nextRefreshLeftSeconds = requestData.nextRefreshLeftSeconds
        products[i].rewards = {
            {num = products[i].num, goodsId = products[i].goodsId}
        }
        local dojo = StoreChestDojo.New()
        dojo:Fill(products[i])
        table.insert(listData, dojo)
        requestData.products = listData
        requestData.activityTimeLeft = checkInt(requestData.remainingTimes)
    end
    return requestData
end

---初始化页面名称
function StoreItem:InitStoreName()
    for i, v in ipairs(VarietyStoreGroup) do
        local config = CfUtils.GetCfVo(AutoIds.IdSetting601, "StoreGeneralVo", v)
        if config then
            local btn = self.CommonTopLabelGroup:Find("Button" .. i)
            if not isNull(btn) then
                local text = btn:Find("Text")
                if not isNull(text) then
                    CfUtils.FillText(text, config.tabName)
                end
            end
        end
    end
end

function StoreItem:EnterStore()
    local openId = self.OpenId
    if not openId then return end

    if self.activityUuid then
        self:RefreshStore()
        return 
    end

    if self._curOpenId then
        self:RefreshTabState(self._curOpenId, false)
    end
    self:RefreshTabState(openId, true)
    self:RefreshStore()
end

function StoreItem:InVisibleGameObject()
    ---@type Engine.UI.UILuaDialog
