function StoreItem:RefreshStore()
    KTool.SetActive(self.BtnExchange, self.OpenId == StoreConstants.OpenIds.Exchange)
    local comp = StoreUtils.GetStoreComp()
    self:GetStoreData(comp)
    self:RefreshRedPoint()
    self:RefreshStoreInfo()
    self:RefreshLoopView()
    self._curOpenId = self.OpenId
end

function StoreItem:RefreshTabState(openId, isSelected)
    local index = self:GetStoreTabIndex(openId)
    if not index then return end
    local btn = self.CommonTopLabelGroup:Find("Button" .. index)
    if not isNull(btn) then
        local item = btn:Find("Item2")
        if not isNull(item) then
            KTool.SetActive(item, isSelected)
        end
    end
end

function StoreItem:GetStoreTabIndex(openId)
    for i, v in ipairs(VarietyStoreGroup) do
        if checkInt(openId) == v then
            return i
        end
    end
end

function StoreItem:RemoveListener()
    if self._onTimeTick ~= nil then
        StoreShared:UnRegisterTimer(self._onTimeTick)
    end

    if self._onRefreshStore ~= nil then
        Events.RemoveListener(StoreConstants.StoreEvents.OnRefreshStore, self._onRefreshStore)
    end

    if self._onRefreshRedPoint ~= nil then
        Events.RemoveListener(StoreConstants.StoreEvents.OnFragsRefresh, self._onRefreshRedPoint)
    end

    if self.activityUuid then
        TimerModule.Instance:RemoveTimer(self:GetActivityTimerName())
    end

    if not isNull(self._closeCo) then
        cs_coroutine.stop(self._closeCo)
    end
end

function StoreItem:RefreshStoreInfo()

    self.SettingStore = StoreShared.SettingStores[self.OpenId]
    self._token = self.SettingStore.voData.token
    StoreShared:RefreshCurrency(self._token)
    
    self:RefreshStoreTime()
end

function StoreItem:RefreshStoreTime()
    if self.ShownData.nextRefreshLeftSeconds >= 0 then
        KTool.SetActive(self.RefreshTimer.gameObject, true)
        local timeStr = StoreUtils.FormatTime(self.ShownData.nextRefreshLeftSeconds, true)
        self.RefreshTimer.text = timeStr
    elseif self.ShownData.activityTimeLeft >= 0 then
        KTool.SetActive(self.RefreshTimer.gameObject, true)
        local timeStr = StoreUtils.FormatTime(self.ShownData.activityTimeLeft, true)
        self.RefreshTimer.text = timeStr
    else
        KTool.SetActive(self.RefreshTimer.gameObject, false)
    end
end

function StoreItem:RefreshLoopView()
    KTool.SetActive(self.ItemCell.gameObject, false)
    local cnt = #self.ShownData.products
    if not self.LoopView.IsListViewInit then
        self._records = {}
        self.LoopView:InitGridView(cnt, Bind(self, self.OnRefreshIndex))
        self._inited = true
    else
        GameUtils.ReloadData(self.LoopView, cnt)
    end

    self.LoopView:MovePanelToItemByIndex(0, 66)
    local trans = self.LoopView.transform:Find("Viewport")
    local size = trans.sizeDelta
    if self.OpenId == StoreConstants.OpenIds.Exchange then
        size.x = -313
        trans.sizeDelta = size
        local pos = trans.anchoredPosition
        pos.x = 313
        trans.anchoredPosition = pos
    else
        size.x = 0
        trans.sizeDelta = size
        local pos = trans.anchoredPosition
        pos.x = 0
        trans.anchoredPosition = pos
    end

    --GameUtils.ReloadData(self.LoopView, cnt)
end

function StoreItem:RefreshRedPoint()
    if self.OpenId == StoreConstants.OpenIds.Exchange then
        StoreUtils.UpdateGroceryExchangeRedPoint()
    end
end

function StoreItem:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellName)
    local data = self.ShownData.products[index + 1]
    self:RefreshCell(cell.transform, data, index + 1)
    return cell
end

---@param data StoreGoodsDojo
function StoreItem:RefreshCell(trans, data, index)
    if not KTool.IsActiveInHierarchy(trans.gameObject) then
        KTool.SetActive(trans.gameObject, true)
    end
    
    --local isSoldOut = data.currentStock == 0
    local isSoldOut = StoreUtils.ProductIsSoldOut(data)
    local isLocked = StoreUtils.ProductIsLocked(data)
    trans = trans:GetChild(0)
    local group = trans.gameObject:GetComponent(typeof(CanvasGroup))
    local isGray = isSoldOut or isLocked
    KTool.SetActive(trans:Find("disableBg").gameObject, isGray)
    local btn = trans.gameObject:GetComponent(typeof(ButtonComp))
    SetButtonAction(btn, function()
        if isSoldOut then
            GameUtils.Toast(localize("商品已售罄"))
