            goodsId        = data.icon,
            goodsNum       = data.num,
            prices         = data.prices,
            maxBuyNum      = data.currentStock,
            remainTime     = data.refreshTime,
            endTime        = self.ShownData.nextRefreshLeftSeconds,
            buyCb          = function (price, buyNum)
                if self.activityUuid then
                    self:ActivityStoreBuyHandler(data.productId, price, buyNum)
                else
                    StoreUtils.RequestProxy(Interfaces.MallShopBuy, self.OpenId, data.productId, buyNum, price.current, price.currency)
                end
            end
        }})
        --UIModule.OpenDialog({ id = Constants.UITypeIds.StoreItemDetailsDialog, parameters = { OpenId = self.OpenId, ItemData = data, activityUuid = self.activityUuid } })
    end)

    --if index <= MaxAnimCount and not isSet(self._records, index) then
    --    --printInfo(index)
    --    local animGroup = trans.gameObject:GetComponent(typeof(CanvasGroup))
    --    local prev = animGroup.alpha
    --    animGroup.alpha = 0
    --    animGroup:DOFade(prev, StoreConstants.FadeInTime):SetDelay(StoreConstants.FadeDelay * index)
    --    table.insert(self._records, index)
    --end

    KTool.SetActive(trans:Find("FinishGroup").gameObject, isSoldOut)
    
    if checkInt(data.currentStock) ~= -1 then
        KTool.SetActive(trans:Find("stock").gameObject, true)
        CfUtils.FillText(trans:Find("stock/num"), tostring(data.currentStock))
