    else
        KTool.SetActive(trans:Find("stock").gameObject, false)
    end

    
    --trans:Find("num").gameObject:GetComponent(typeof(TextComp)).text = string.format(StoreConstants.StackNum, data.num)

    local goodsId = checkNumber(data.icon) == 0 and data.goodsId or checkNumber(data.icon)
    
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if vo == nil then
