    end
end

function StoreItem:RefreshPrice(trans, price, currency)
    if not KTool.IsActiveInHierarchy(trans.gameObject) then
        KTool.SetActive(trans.gameObject, true)
    end
    trans:Find("Text").gameObject:GetComponent(typeof(TextMeshProUGUI)).text = price
    local img = trans:Find("icon").gameObject:GetComponent(typeof(ImageComp))
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(currency)
    StoreShared:LoadSpriteAsync(img, path)
end

function StoreItem:RefreshUnlock(trans, unlock)
    if not KTool.IsActiveInHierarchy(trans.gameObject) then
        KTool.SetActive(trans.gameObject, true)
    end
    if unlock == nil then
        printInfo("??")
    end
    local textComp = trans:Find("btm/Text").gameObject:GetComponent(typeof(TextComp))
    if unlock.targetType ~= nil and unlock.targetNum ~= nil then
        textComp.text = GameUtils.GetUnlockDescr(unlock.targetType, unlock.targetNum)
    else
        textComp.text = "?"
    end
end

function StoreItem:OnTimeTick()
    if self._secondCount == nil then
        self._secondCount = 0
    end
    self._secondCount = self._secondCount + 1
    if self._secondCount > self._trulyRefresh then
        self._secondCount = self._secondCount - self._trulyRefresh
        --重新计算下次刷新时间
        self:CalcRefreshTime()
        self:RefreshStoreTime()
        if self.activityUuid then
            if self.ShownData.activityTimeLeft == 0 then
                GameUtils.Toast(localize("活动已结束"))
                UIModule.BackDialog()
            end
        else
            if self.ShownData.nextRefreshLeftSeconds == 0 then
                GameUtils.Request(Interfaces.StoreHome, {}, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        StoreUtils.RefreshStore(response.data)
                    end

                end)
            end
        end
        
    end
end

